test("IParent deserialization fail", () => {
  const jsonable = "This is not a IParent.";

  const instanceOrError = OurJsonization.parentFromJsonable(
    jsonable
  );
  expect(instanceOrError.error.message).toStrictEqual(
    "Expected a JSON object, but got: string"
  );
});

